posthog.init('<ph_project_token>', {
    api_host: 'https://us.i.posthog.com',
    defaults: '2026-05-30',
    opt_out_capturing_by_default: true,
})
function onConsentChange(hasConsented) {
    if (hasConsented) {
        posthog.opt_in_capturing()
    } else {
        posthog.opt_out_capturing()
    }
}

persistence: 'localStorage+cookie' (default) | 'cookie' | 'localStorage' | 'sessionStorage' | 'memory'

// Dynamic switch example from docs:
const handleCookieConsent = (consent) => {
  posthog.set_config({ persistence: consent === 'yes' ? 'localStorage+cookie' : 'memory' });
  localStorage.setItem('cookie_consent', consent);
};

posthog.capture('quote_form_submitted', {
    equipment_tier: 'standard',
    lead_source: 'organic'
});

